  let fullText = "";
  for (const chunk of f) {
    if (Array.isArray(chunk) && typeof chunk[1] === 'string') {
      fullText += chunk[1];
    }
  }

  // Search for filters or facets in fullText
  const hasSpecialty = fullText.includes("specialty") || fullText.includes("Specialty");
  const hasFacets = fullText.includes("facets") || fullText.includes("filters");

  // Extract any filter definitions or availableFilters
  const matches = fullText.match(/"filterGroup[^"]*":\{[^\}]*\}/g);

  return {
    fullTextLength: fullText.length,
    hasSpecialty,
    hasFacets,
    sampleMatches: matches ? matches.slice(0, 5) : null
  };
});

