const data = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('h3')).filter(h => h.querySelector('a[href*="/physician/"]') || h.querySelector('a[href*="/providers/"]'));

  return cards.map(h3 => {
    const a = h3.querySelector('a');
    let parent = h3.parentElement;
    for (let i = 0; i < 8; i++) {
      if (!parent.parentElement) break;
      parent = parent.parentElement;
      if (parent.innerText.includes('Star') || parent.innerText.includes('ratings') || parent.innerText.includes('miles')) break;
    }

    // Extract rating
    const ratingMatch = parent.innerText.match(/Rated\s+([0-9.]+)\s+out of 5/i) || parent.innerText.match(/([0-9.]+)\s+from\s+\d+\s+ratings?/i);
    const reviewsMatch = parent.innerText.match(/from\s+(\d+)\s+ratings?/i);
    const writtenReviewsMatch = parent.innerText.match(/(\d+)\s+written\s+reviews?/i);
    const distanceMatch = parent.innerText.match(/([0-9.]+\s*mi)/i);
    const specialtyMatch = parent.innerText.match(/Specialty:\s*([^\n\r|]+)/i);

    return {
      name: a ? a.innerText.trim() : h3.innerText.trim(),
      url: a ? a.href : null,
      rating: ratingMatch ? ratingMatch[1] : null,
      ratingsCount: reviewsMatch ? reviewsMatch[1] : null,
      writtenReviewsCount: writtenReviewsMatch ? writtenReviewsMatch[1] : null,
      distance: distanceMatch ? distanceMatch[1] : null,
      specialty: specialtyMatch ? specialtyMatch[1].trim() : null
    };
  });
});

