const pedsResults = await browserjs(tabId, async () => {
  const url = 'https://www.healthgrades.com/usearch?what=Pediatrics&entityCode=PS740&searchType=PracticingSpecialty&where=Hollywood%2C%20CA&pt=34.100330%2C-118.327300&distances=5&rating=4&pageNum=1&sort.provider=bestmatch&state=CA&zip=90028';
  const res = await fetch(url);
  const text = await res.text();
  const parser = new DOMParser();
  const doc = parser.parseFromString(text, 'text/html');

  const h3s = Array.from(doc.querySelectorAll('h3 a')).filter(a => a.href.includes('/physician/') || a.href.includes('/providers/'));
  return h3s.map(a => {
    let parent = a.parentElement;
    for (let i = 0; i < 8; i++) {
      if (!parent.parentElement) break;
      parent = parent.parentElement;
      if (parent.innerText.includes('Star') || parent.innerText.includes('ratings')) break;
    }
    return {
      name: a.innerText.trim(),
      url: a.href,
      text: parent.innerText.replace(/\n+/g, ' | ')
    };
  });
});

